fn build_io_effects(functions: ref list<review_function_fact>, calls: ref list<call_fact>, uses: ref list<module_use>) -> list<str> {
    let mut inferred: list<str> = list();
    let mut function_index = 0;
    while function_index < list_len(ref functions) {
        let entry = list_get(ref functions, function_index);
        match entry {
            Some(value) => {
                if value.owns_process or function_has_direct_io(ref calls, value.module, value.name) {
                    push_if_missing(mutref inferred, function_internal_name(value.module, value.name));
                }
            },
            None => {
            },
        }
        function_index = function_index + 1;

fn review_process_types(shapes: ref list<checked_type_shape>, fields: ref list<checked_field_decl>, variants: ref list<checked_variant_decl>, payloads: ref list<checked_variant_payload_decl>) -> list<i32> {
    let mut owned: list<i32> = list();
    let mut index = 0;
    while index < list_len(ref shapes) {
        match list_get(ref shapes, index) {
            Some(shape) => { match shape.kind { checked_type_process => { list_push(mutref owned, shape.id); }, _ => {}, } },
            None => {},
        }
        index = index + 1;
    }
    if list_len(ref owned) == 0 { return list(); }
    // A monotone type-ID closure handles nested containers without depending on
    // spelling, declaration order, or recursion through borrowed pointees.
    let mut changed = true;
    while changed {
        changed = false;
        index = 0;
        while index < list_len(ref shapes) {
            match list_get(ref shapes, index) {
                Some(shape) => {
                    if not list_contains_i32(ref owned, shape.id) {
                        let mut contains = false;
                        match shape.kind {
                            checked_type_list => { contains = list_contains_i32(ref owned, shape.arg1_id); },
                            checked_type_option => { contains = list_contains_i32(ref owned, shape.arg1_id); },
                            checked_type_result => { contains = list_contains_i32(ref owned, shape.arg1_id) or list_contains_i32(ref owned, shape.arg2_id); },
                            checked_type_named => {
                                let mut field_index = 0;
                                while field_index < list_len(ref fields) {
                                    match list_get(ref fields, field_index) {
                                        Some(field) => {
                                            if field.module_name == shape.origin_module and field.type_name == shape.name and list_contains_i32(ref owned, field.field_type_id) { contains = true; }
                                        },
                                        None => {},
                                    }
                                    field_index = field_index + 1;
                                }

index = 0;
while index < list_len(ref expressions) {
    match list_get(ref expressions, index) {
        Some(value) => {
            // Names and fields are views of existing bindings, not newly
            // owned temporaries. Borrow nodes never add cleanup authority.
            let mut temporary = true;
            match value.kind {
                checked_expr_name => { temporary = false; },
                checked_expr_field => { temporary = false; },
                checked_expr_ref => { temporary = false; },
                checked_expr_mutref => { temporary = false; },
                _ => {},
            }
            if temporary and not value.is_borrow and list_contains_i32(ref owned_types, value.type_id) and not list_contains_i32(ref owners, value.function_id) { list_push(mutref owners, value.function_id); }
        },
        None => {},
    }
    index = index + 1;
}
return owners;

fn checked_call_kind(expr: checked_expr) -> str {
    match expr.target_kind {
        checked_target_function => { if expr.target_origin_module != "" and expr.target_origin_module != "__builtin__" { return "function"; } },
        checked_target_builtin_function => { if expr.target_origin_module == "__builtin__" { return "builtin"; } },
        checked_target_constructor => { if expr.target_origin_module != "" and expr.target_origin_module != "__builtin__" { return "variant"; } },
        checked_target_builtin_constructor => { if expr.target_origin_module == "__builtin__" { return "builtin_variant"; } },
        _ => {},
    }
    return "";
}

pub fn checked_evidence_calls(calls: ref list<call_fact>, expressions: ref list<checked_expr>, diags: mutref list<diag>) -> list<call_fact>
audit {
    intent("Join source call sites to checked targets once, without guessing origin from spelling");
    mutates(diags);
    effects();

let mut selected_ranges: list<review_call_range> = list();
for call in calls {
    if call.module != current_module or call.function_name != current_function {
        current_module = call.module;
        current_function = call.function_name;
        selected_ranges = list();
        for range in ranges {
            if range.module == current_module and range.function_name == current_function { list_push(mutref selected_ranges, range); }
        }
    }
    let mut origin = "";
    let mut kind = "";
    let mut expr_start = -1;
    let mut expr_end = -1;
    let mut error_name = "";
    let mut matched = 0;
    for range in selected_ranges {
        let mut index = range.start;
        while index < range.end {
            match list_get(ref sites, index) {
                Some(site) => {
                    if site.at == call.at and site.name == call.name {
                        matched = matched + 1;
                        origin = site.checked_origin;
                        kind = site.checked_kind;
                        expr_start = site.checked_start;
                        expr_end = site.checked_end;
                        error_name = site.checked_error_name;
                    }
                },
                None => {},
            }
            index = index + 1;
        }
    }
    if matched != 1 or kind == "" {
        list_push(mutref diags, make_diagnostic("NQ-INTERNAL-012", diag_internal, diag_error, call.module, call.at, call.at + str_len(call.name), "stage1 internal error: call evidence lacks a unique checked target", "", ""));
    }
    list_push(mutref out, call_fact { module: call.module, function_name: call.function_name, name: call.name, at: call.at, arg_count: call.arg_count, checked_origin: origin, checked_kind: kind, checked_start: expr_start, checked_end: expr_end, checked_error_name: error_name });

fn builtin_function_param_is_borrow(name: str, index: i32) -> bool {
    if name == "process_start" and (index == 1 or index == 3) {
        return true;
    }
    if name == "process_terminate" and index == 0 {
        return true;
    }
    if name == "list_push" and index == 0 {
        return true;
    }
    if name == "list_len" and index == 0 {
        return true;
    }
    if name == "list_get" and index == 0 {
        return true;
    }
    if name == "run_process" and index == 1 {
        return true;
    }
    if (name == "bytes_len" or name == "bytes_get") and index == 0 {
        return true;
    }
    if (name == "stdout_write_bytes" or name == "stderr_write_bytes" or name == "str_from_bytes") and index == 0 {
        return true;
    }
    if (name == "write_file_bytes" or name == "atomic_write_file") and index == 1 {
        return true;
    }
    if (name == "io_err_kind" or name == "io_err_operation" or name == "io_err_path" or name == "io_err_other_path" or name == "io_err_os_code") and index == 0 {
        return true;
    }
    return false;

static int nq_process_kill(pid_t pid) {
    int result;
    do { result = kill(pid, SIGKILL); } while (result < 0 && errno == EINTR);
    return result < 0 && errno != ESRCH ? errno : 0;
}

/* Legacy launches do not own a process group. Retain just the exact child
 * anchor, returning it live only so the caller can unlink captures and fail. */
static int nq_process_legacy_wait(pid_t* pid, int* status, bool abort_child) {
    int first_error = 0;
    if (!abort_child) {
        first_error = nq_process_reap_pid(pid, status);
        if (*pid == 0) return first_error;
    }
    for (int attempt = 0; attempt < 2 && *pid > 0; attempt++) {
        bool exited = false;
        int error = nq_process_probe_pid(pid, &exited, false);
        if (error == 0 && !exited) error = nq_process_kill(*pid);
        if (error == 0) error = nq_process_reap_pid(pid, status);
        if (first_error == 0) first_error = error;
    }
    if (*pid > 0) {
        bool exited = false;
        int error = nq_process_probe_pid(pid, &exited, false);
        if (error != 0 && *pid > 0) error = nq_process_probe_pid(pid, &exited, false);
        if (error == 0 && exited) {
            error = nq_process_reap_pid(pid, status);
            if (error != 0 && *pid > 0) (void)nq_process_reap_pid(pid, status);
        }
        if (*pid > 0) (void)nq_process_probe_pid(pid, &exited, false);
    }
    return first_error != 0 ? first_error : (*pid > 0 ? EIO : 0);
}

static bool nq_process_pump(NQProcessState* state, NQ_Option__instant deadline, bool cancel,
                            const char* operation, NQIoErr* error) {
    bool draining = false;
    size_t output_remaining = 0, error_remaining = 0;
    while (true) {
        bool exited = false;
        int system_error = nq_process_probe(state, &exited);
        if (system_error != 0) { *error = nq_errno_io_err(operation, NULL, NULL, system_error); return false; }
        int timeout = 10;
        bool expired = false;
        if (!exited && !state->signalled && !cancel && deadline.tag == NQ_Option__instant_Tag_Some) {
            int64_t now;
            if (!nq_clock_ns(CLOCK_MONOTONIC, operation, &now, error)) return false;
            expired = deadline.data.Some._0._ns <= now;
            if (!expired) {
                int64_t remaining = deadline.data.Some._0._ns - now;
                if (remaining < INT64_C(10000000)) timeout = (int)((remaining + 999999) / 1000000);
            }
        }
        if (!state->signalled && (exited || expired || cancel)) {
            /* A fresh observation wins over a deadline/cancellation action. */
            system_error = nq_process_signal_owned(state, &exited);
            if (system_error != 0) { *error = nq_errno_io_err(operation, NULL, NULL, system_error); return false; }
            state->outcome.timed_out = !exited && expired;
            state->outcome.cancelled = !exited && cancel;
            nq_process_close_fd(&state->input_fd);
        }
        if (exited && !draining) {
            system_error = nq_process_signal_terminal(state);
            if (system_error != 0) { *error = nq_errno_io_err(operation, NULL, NULL, system_error); return false; }
            /* The direct child's writes are now complete. Snapshot queued
             * bytes instead of waiting for EOF from an escaped descendant. */
            system_error = nq_process_queued(state->output_fd, &output_remaining);
            if (system_error == 0) system_error = nq_process_queued(state->error_fd, &error_remaining);
            if (system_error != 0) { *error = nq_errno_io_err(operation, NULL, NULL, system_error); return false; }

NQ_Result__process_outcome__io_err nq_process_wait(NQ_process child, NQ_Option__instant deadline) {
    NQIoErr error;
#ifdef __linux__
    if (child._state == NULL) error = nq_invalid_input_io_err("process_wait", NULL, NULL, "inert process handle");
    else if (deadline.tag != NQ_Option__instant_Tag_None && deadline.tag != NQ_Option__instant_Tag_Some)
        error = nq_invalid_input_io_err("process_wait", NULL, NULL, "invalid deadline option");
    else if (child._state->ready || nq_process_pump(child._state, deadline, false, "process_wait", &error)) {
        NQ_process_outcome outcome = child._state->outcome;
        child._state->outcome = (NQ_process_outcome){0};
        nq_process_drop(&child);
        return (NQ_Result__process_outcome__io_err){ .tag = NQ_Result__process_outcome__io_err_Tag_Ok, .data.Ok._0 = outcome };
    }
#else
    (void)deadline;
    error = nq_unsupported_io_err("process_wait", NULL);
#endif
    nq_process_drop(&child);
    return (NQ_Result__process_outcome__io_err){ .tag = NQ_Result__process_outcome__io_err_Tag_Err, .data.Err._0 = error };
}

NQ_Result__unit__io_err nq_process_terminate(NQ_process* child) {
    NQIoErr error;
#ifdef __linux__
    if (child == NULL || child->_state == NULL)
        return nq_unit_err(nq_invalid_input_io_err("process_terminate", NULL, NULL, "inert process handle"));
    if (child->_state->ready || nq_process_pump(child->_state,
        (NQ_Option__instant){ .tag = NQ_Option__instant_Tag_None }, true, "process_terminate", &error)) return nq_unit_ok();
#else
    error = nq_unsupported_io_err("process_terminate", NULL);
#endif
    nq_process_drop(child);
    return nq_unit_err(error);

